8	function parseFrontmatter(raw: string): { meta: Record<string, string>; body: string } {
9	  const match = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/)
10	  if (!match) return { meta: {}, body: raw }
11	  const meta: Record<string, string> = {}
12	  for (const line of match[1].split('\n')) {
13	    const colonIdx = line.indexOf(':')
14	    if (colonIdx === -1) continue
15	    const key = line.slice(0, colonIdx).trim()
16	    let val = line.slice(colonIdx + 1).trim()
17	    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
18	      val = val.slice(1, -1)
19	    }
20	    if (key) meta[key] = val
21	  }
22	  return { meta, body: match[2].replace(/^\n+/, '') }
23	}
