25	function serializeTemplate(meta: Record<string, string>, body: string): string {
26	  const lines = Object.entries(meta)
27	    .filter(([, v]) => v !== undefined)
28	    .map(([k, v]) => {
29	      if (v.includes(':') || v.includes('#') || v.includes('"')) {
30	        return `${k}: "${v.replace(/"/g, '\\"')}"`
31	      }
32	      return `${k}: ${v}`
33	    })
34	  return `---\n${lines.join('\n')}\n---\n\n${body}`
35	}
